dotaz.sql:
select *
from zbozi z where not exists(
    select *
    from zakaznik o
    where not exists(
        select z
        from prodej p
        where o.id_osoba = p.id_osoba and z.id_zbozi = p.id_zbozi
    )
)

select * from zakaznik
except
select o.* from zakaznik o join prodej p using(id_osoba) where id_zbozi = ( select id_zbozi from zbozi z where not exists( select * from zakaznik o where not exists( select z from prodej p where o.id_osoba = p.id_osoba and z.id_zbozi = p.id_zbozi ) ) ) ;

create or replace view pokoje as
select * from pokoj p
where p.pocet_postel > 2
and exists (
  select * from zakaznik z
  where z.id_pokoj = p.id_pokoj and z.vernostni_bonus > 3
);

select * from pokoje;

create or replace view pokoje as
select * from pokoj p
where p.pocet_postel > 2
and exists (
  select * from zakaznik z
  where z.id_pokoj = p.id_pokoj and z.vernostni_bonus > 3
);

select * from pokoje
where pocet_postel > 9;

begin;

select * from osoba;

delete from osoba where id_osoba not in (
  select a.id_osoba from zakaznik a
  union
  select z.id_osoba from zamestnanec z
);

select * from osoba;

rollback;

select o.jmeno, (select count(*) from kontrakt k where k.id_osoba = z.id_osoba) as pocet_kontraktu
from zamestnanec z
join osoba o using(id_osoba);

select o.jmeno, g.id_kontrakt, g.odmena
from (
    select k.id_kontrakt, k.odmena, z.id_osoba from kontrakt k
    join zamestnanec z using(id_osoba)
) as g
join osoba o using(id_osoba)

select count(*) as pocet_nakupu
from zbozi
cross join zakaznik;

select id_osoba from zamestnanec where id_osoba not in( select id_osoba from kontrakt );
select id_osoba from zamestnanec z where not exists( select 3 from kontrakt k where k.id_osoba = z.id_osoba );
select id_osoba from zamestnanec except select id_osoba from zamestnanec join kontrakt using(id_osoba);

begin;

select *
from zamestnanec
where popis='Pre-emptive foreground hardware';

update zamestnanec
set popis = 'neco'
where popis = 'Pre-emptive foreground hardware'
and id_osoba in (
select id_osoba
from kontrakt
where uspesne_splneno = 'true'
);

select *
from zamestnanec
where popis='neco';

rollback;

begin;
select count(*) from osoba where id_osoba not in( select id_osoba from zamestnanec union select id_osoba from zakaznik );
insert into zakaznik(id_osoba, id_pokoj, vernostni_bonus) select id_osoba, null as id_pokoj, 0 as vernostni_bonus from osoba where id_osoba not in( select id_osoba from zamestnanec union select id_osoba from zakaznik );
select count(*) from osoba where id_osoba not in( select id_osoba from zamestnanec union select id_osoba from zakaznik );
rollback;
